-- GENERATED by `wfj generate` from data/gossip/gossip-ba.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["ba015798fb869929"] = { "Vuoi imparare a usare una nuova arma, eh? Beh, allora dovresti parlare con Bixi o Buliwyf alla bottega d'armi Timberline Arms, <ragazzo/ragazza>. Conoscono le armi, dalle asce agli... ehm... zweihander.", "." },
  ["ba03416b9867401c"] = { "Anathera e Latherion combatterono schiena contro schiena dove la battaglia era più fitta. Due amanti decisi a sopravvivere insieme alla guerra.", "." },
  ["ba04153507b8795c"] = { "Sappiano tutti che {name}, {class} dell'⟦Horde=Orda⟧, ha conquistato il rispetto imperituro del Capoguerra. Ha condotto con grande diplomazia i rapporti con il ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e ha compiuto per loro azioni valorose a nostro nome. Ha fatto molto più di quanto il dovere richiedesse. Tre urrà per {name}, <un/una> <vero/vera> <eroe/eroina> dell'⟦Horde=Orda⟧!", "." },
  ["ba05ca0a7b6376eb"] = { "Qui dimora un orrore indicibile, mortale. C'Thun e i suoi adoratori non sono solo un affronto alla natura: la loro esistenza preannuncia la distruzione di Azeroth come la conosciamo.\n\nMerithra si sacrificò mille anni fa insieme a Caelestrasz e Arygos, perché anche loro lo sapevano. Siamo qui per il nostro giuramento di tornare per loro, ma siamo qui anche perché C'Thun va fermato!", "." },
  ["ba068478543d2ab4"] = { "Si dice che questa fiera della notte sia docile in presenza degli elfi della notte e dei loro alleati, il che la rende un'avversaria ancora più degna. Il percorso di caccia di Shadumbra la porta dal ⟦Raynewood Retreat=Rifugio di Legnovivo⟧, a ovest di qui, fino alle terre che si trovano ancora più a ovest. Il suo pelo è nero come la pece, e la sua velocità non va sottovalutata.", "." },
  ["ba12afb24407defe"] = { "No! Anaya... Anaya! Non lasciarmi! Ti prego...", "." },
  ["ba143114700d8215"] = { "Molto interessante. Ma se è così, allora la mia teoria è sbagliata. Devo rileggere le altre sezioni per capire cosa mi è sfuggito.", "." },
  ["ba18a1303a33f13d"] = { "Sei appena <uscito/uscita> da una spedizione? Mi hai portato qualcosa?", "." },
  ["ba2510b4ee376701"] = { "Hai l'aria di un fabbro, tu. Fuliggine sotto le unghie, acciaio nelle ossa. Già, hai proprio il sangue del fabbro nelle vene. Il che vuol dire che sei <venuto/venuta> da me per imparare una cosa o due: be', <ragazzo/ragazza>, prendi un martello. Vediamo cosa posso insegnarti.", "." },
  ["ba27c2d78b4a03c5"] = { "{name}, sento che la grande bestia si avvicina...", "." },
  ["ba2b6f5757d9b396"] = { "Sono <pronto/pronta> a piazzare il segnalatore, Mulv. Dammi un segnalatore.", "." },
  ["ba38ad3a55201654"] = { "Questa pianta di sbocciavento spicca come un faro di luce nell'oscurità di ⟦Felwood=Vilbosco⟧. Bacche grosse e succose pendono dalla pianta, mature e pronte da cogliere.", "." },
  ["ba3db556cf459bbd"] = { "Allora, {class}? Ha creduto al nostro stratagemma, o le cose vanno peggio di quanto avessi stimato?\n\nRenderti prezios<o/a> agli occhi di Neeru renderà molto più facile la nostra infiltrazione nel ⟦Shadow Council=Concilio dell'Ombra⟧. Avrà un sacco di informazioni che potremo usare per stanare chi vorrebbe distruggere tutto ciò che abbiamo costruito a Durotar.", "." },
  ["ba3e944edf340888"] = { "⟦Polar Gloves=Guanti Polari⟧.", "." },
  ["ba49f61b1a16cff1"] = { "Abbiamo molte scorte, ma ce ne servono ancora tante per lanciare un assalto di terra nel ⟦Field of Strife=Pian della Discordia⟧.", "." },
  ["ba53f6aec8aeb168"] = { "So già molte cose sullo stile. Ora si tratta solo di padroneggiare le tecniche per lavorare il cuoio. Per fortuna Simon è davvero gentile ad aiutarmi a impararle.", "." },
  ["ba59c4d32b9d9da9"] = { "Hai qualche faccenda da sbrigare con me, {class}?", "." },
  ["ba63556b41816bc1"] = { "Ho resistito ai veleni dei Reietti, {name}, e ora so cosa va fatto.", "." },
  ["ba69630a3240e9ea"] = { "%s si agita a disagio.", "." },
  ["ba71fe0a2a891920"] = { "Dov'è la mia pancetta?", "." },
  ["ba7790d67a72d63b"] = { "State all'erta! Gli orchi e i loro alleati sono vicini!", "." },
  ["ba817b7fa05125b7"] = { "Degli intrusi hanno assalito il nostro covo. State in guardia!", "." },
  ["ba92ba82440a51db"] = { "Sciamano", "." },
  ["ba93dd58a412cb14"] = { "Erano centinaia, imprigionati dal suo incantesimo. Ora solo pochi restano nelle loro prigioni. A volte ci parlava.", "." },
  ["ba97186b3b749cca"] = { "Tutte le bottiglie su questo tavolo sono pozioni che ho preparato oggi. E dicono che una pentola guardata non bolle mai. Ah!", "." },
  ["ba974a0ebff955ea"] = { "Raggiungimi all'accampamento di Maxwell. Lì esamineremo le prossime fasi del piano e cercheremo un modo per decifrare le mie tavolette senza l'anello di decrittazione.", "." },
  ["baa34344817c9ea8"] = { "Va' a Orgrimmar, la città degli orchi: lo troverai nella ⟦Valley of Honor=Valle dell'Onore⟧, in una bottega chiamata Arms of Legend.", "." },
  ["baa519401413d6b5"] = { "Molti animali hanno perso la vita perché potessimo ottenere questi materiali. Non prendere alla leggera il loro sacrificio, {name}. Tratta il cuoio con il rispetto che merita.", "." },
  ["baad1b7c08a6fe11"] = { "Mai visto nessuno muoversi così in fretta in tutta la mia vita.", "." },
  ["bac10d15ab5f18a2"] = { "Salve, {class}. Sono Jessir Moonbow. Vengo da Darnassus in cerca di due amici che sono venuti a cercare tracce del ⟦Shadow Council=Concilio dell'Ombra⟧ a ⟦Felwood=Vilbosco⟧.\n\nSembra che quelle creature immonde, che si attribuiscono gran parte delle sofferenze della razza degli orchi, cerchino di riconquistare parte del loro potere.\n\nI miei due amici sono andati a indagare a Jaedenar per capire una volta per tutte cosa stesse accadendo.\n\nContavo di trovarli qui al mio arrivo, ma ormai sono in ritardo di giorni.", "." },
  ["bac2ded24263533e"] = { "%s è vuoto, a parte qualche briciola e un'enorme piuma verde.", "." },
  ["bac6a8695767839e"] = { "Forse dovresti parlare in questi dispositivi amplificatori di suono attaccati ai miei PUGNI DELLA FURIA.", "." },
  ["bac7eb05068d6691"] = { "Io sono Gath'Ilzogg! E tu sei <un/una> {race} sull'orlo della morte!", "." },
  ["bacca2abc90e5357"] = { "Sembra che tu voglia parlare con Maginor Dumas! Di solito lo trovi nel Wizard's Sanctum, nel ⟦Mage Quarter=Quartiere dei Maghi⟧. Certo, non si sa mai quando o dove quei maghi si teletrasporteranno.", "." },
  ["bad6e111445ebb09"] = { "Puoi incantare la mia ascia? Vorrei un incantamento permanente. Magari più tardi, allora. Cerca Godan's Runeworks all'estremità ovest di The Drag, vicino alla Valle della Saggezza.", "." },
  ["bad9e4775c657dce"] = { "Vediamo la tua attrezzatura da pesca.", "." },
  ["bada152a507b02bf"] = { "Ti do il benvenuto, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di addestrarti.\n\nCorrono voci di discordia nel ⟦Cenarion Circle=Circolo Cenariano⟧, ma non dovresti dare retta a queste chiacchiere. Il nostro Arcidruido, Fandral Staghelm, guida noi e tutta Teldrassil verso la gloria!", "." },
  ["bae33dc03ca17c6f"] = { "Se vuoi sapere degli arrivi e delle partenze di carovane e mercanti qui all'⟦Splintertree Post=Avamposto di Troncorotto⟧, per tua fortuna sono proprio chi cerchi. Per tua sfortuna, però, la gente non mi piace.\n\nSe vuoi qualcosa, sbrigati.", "." },
  ["baeab5811015f405"] = { "Cacciatori, voi e le vostre fastidiose cerbottane!", "." },
  ["baebdaecbf95703e"] = { "UAAAHHH!!!", "." },
  ["baef015b101933f8"] = { "Esatto, ehm, <ragazzo/ragazza>, tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧ e l'ultima parte dovrebbe arrivare entro un giorno. Dopodiché non ci resterà che aspettare e vedere chi si farà avanti per ricomporre lo Scettro delle Sabbie Mutevoli e suonare il gong sull'Altare dello Scarabeo. Solo quando ciò accadrà la guerra comincerà ad aprire le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["baf55cb0ddc7efc9"] = { "In realtà è semplice. Permettimi di riassumere...", "." },
  ["baf6ea6ce9d1eede"] = { "Questi mucchi di legno e paglia avranno anche pietà, ma il Re dei Lich no!", "." },
  ["bafc8afd8f3a3612"] = { "%s ripone gli oggetti che {name} gli ha dato.", "." },
  ["baffc93164412900"] = { "Assaggia la nostra Birra dei ⟦Dark Iron=Ferroscuro⟧. Ho sentito che i nani da queste parti non ne hanno mai abbastanza.", "." },
})
